from scipy.integrate import solve_ivp


def transitorio(M, K, C, T, t_fin, n=2000):
    nd = M.shape[0]
    Minv = np.linalg.inv(M)

    def f(t, y):
        th, om = y[:nd], y[nd:]
        return np.concatenate([om, Minv @ (np.asarray(T(t)) - C @ om - K @ th)])

    t = np.linspace(0, t_fin, n)
    sol = solve_ivp(f, (0, t_fin), np.zeros(2 * nd), t_eval=t, rtol=1e-8, atol=1e-10)
    return sol.t, sol.y[:nd]
